Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "padding": {
    "top": 10,
    "left": 5,
    "right": 5,
    "bottom": 5
  },
  "transform": [
    {
      "calculate": "[''Sun'',''Mon'',''Tue'',''Wed'',''Thu'',''Fri'',''Sat''][day(toDate(datum[''date'']))]",
      "as": "Day Label"
    },
    {
      "calculate": "datum[''alcohol_consumption_count''] >= 3 ? ''3+'' : format(datum[''alcohol_consumption_count''], ''.0f'')",
      "as": "Drink Band"
    }
  ],
  "mark": {
    "type": "rect",
    "cornerRadius": 4,
    "stroke": "#FFFFFF",
    "strokeWidth": 2,
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "timeUnit": "yearweek",
      "axis": {
        "title": null,
        "format": "%b",
        "tickCount": "month",
        "labelAngle": 0,
        "labelColor": "#667085",
        "labelFontSize": 12,
        "labelPadding": 8,
        "grid": false,
        "domain": false,
        "ticks": false
      }
    },
    "y": {
      "field": "Day Label",
      "type": "ordinal",
      "sort": [
        "Mon",
        "Tue",
        "Wed",
        "Thu",
        "Fri",
        "Sat",
        "Sun"
      ],
      "axis": {
        "title": null,
        "labelColor": "#667085",
        "labelFontSize": 11,
        "labelPadding": 6,
        "grid": false,
        "domain": false,
        "ticks": false
      }
    },
    "color": {
      "field": "Drink Band",
      "type": "ordinal",
      "scale": {
        "domain": [
          "0",
          "1",
          "2",
          "3+"
        ],
        "range": [
          "#EEF1F6",
          "#FFD166",
          "#F59E0B",
          "#E45756"
        ]
      },
      "legend": {
        "title": "Drinks",
        "orient": "top",
        "direction": "horizontal",
        "titleColor": "#344054",
        "labelColor": "#667085",
        "symbolType": "square",
        "symbolSize": 130,
        "offset": 4
      }
    },
    "tooltip": [
      {
        "field": "date",
        "type": "temporal",
        "title": "Date",
        "format": "%B %d, %Y"
      },
      {
        "field": "alcohol_consumption_count",
        "type": "quantitative",
        "title": "Drinks",
        "format": ".0f"
      },
      {
        "field": "sleep_hours",
        "type": "quantitative",
        "title": "Sleep (hours)",
        "format": ".1f"
      },
      {
        "field": "workout_minutes",
        "type": "quantitative",
        "title": "Workout Minutes",
        "format": ".0f"
      },
      {
        "field": "active_energy_kcal",
        "type": "quantitative",
        "title": "Active Energy",
        "format": ",.0f"
      }
    ]
  },
  "config": {
    "view": {
      "stroke": null
    },
    "background": null
  }
}'
